function applyQualityFilter(items) {
  const BOOST_QUANT = {
    'arxiv.org': 10, 'ssrn.com': 10, 'papers.ssrn.com': 10, 'papers.nber.org': 6,
    'quantpedia.com': 8, 'quantitativo.com': 8, 'robotwealth.com': 8,
    'quant.stackexchange.com': 7, 'quantstart.com': 7,
    'quantocracy.com': 6, 'quantifiedstrategies.com': 6, 'alphaarchitect.com': 6,
    'quantconnect.com': 5, 'reddit.com/r/algotrading': 5,
    'tradingview.com/script': 4, 'cmegroup.com': 4,
  };
  const BOOST_NEWS = {
    'reuters.com': 7, 'bloomberg.com': 7, 'wsj.com': 7, 'ft.com': 7,
    'cnbc.com': 6, 'marketwatch.com': 5, 'barchart.com': 5,
    'zerohedge.com': 4, 'tradingview.com/news': 4,
  };
  const DOWNRANK = {
    'investopedia.com': 10, 'youtube.com/shorts': 10,
    'medium.com': 8, 'benzinga.com': 8,
    'marketbeat.com': 7, 'fool.com': 7,
    'seekingalpha.com': 6, 'towardsdatascience.com': 6,
    'businessinsider.com': 7, 'cryptoslate.com': 8,
    'tradingkey.com': 9,
  };
  const DISCARD_DOMAINS = ['pinterest.com','tiktok.com','facebook.com','instagram.com',
    'yoforex.org','yellow.com'];
  // Path patterns must be specific enough to avoid English-word collisions.
  // Removed bare '-ea' (false-positives on east/earnings/ahead).
  const DISCARD_PATHS = [
    'reddit.com/r/wallstreetbets','/binary-options','/forex-signals','/get-rich-',
    '-ea-v','-mt5/','/free-download','/price-prediction','/nft-market','pudgy-penguins',
  ];

  function urlMatches(url, pattern) { return url.toLowerCase().includes(pattern.toLowerCase()); }
  function domainOf(url) { try { return new URL(url).hostname.replace(/^www./,''); } catch { return ''; } }
  function bestKey(map, url) {
    const keys = Object.keys(map).sort((a, b) => b.length - a.length);
    for (const k of keys) if (urlMatches(url, k)) return { key: k, weight: map[k] };
    return null;
  }
  const titleLooksSpammy = (t) => /price prediction|free download|EA V|signals telegram|guaranteed|pump|moonshot|gem altcoin|get rich/i.test(t || '');

  const filtered = [];
  for (const it of items) {
    const url = it.url || (it.json && it.json.url) || '';
    if (!url) continue;
    const dom = domainOf(url);
    if (DISCARD_DOMAINS.some(d => dom.includes(d))) continue;
    if (DISCARD_PATHS.some(p => urlMatches(url, p))) continue;
    const title = it.title || (it.json && it.json.title) || '';
    if (titleLooksSpammy(title)) continue;
    const dr = bestKey(DOWNRANK, url);
    if (dr && dr.weight >= 10) continue;
    const boostQ = bestKey(BOOST_QUANT, url);
    const boostN = bestKey(BOOST_NEWS, url);
    let score = 0;
    if (boostQ) score += boostQ.weight;
    if (boostN) score += boostN.weight;
    if (dr) score -= dr.weight * 0.5;
    filtered.push({ ...it, _qualityScore: score });
  }
  filtered.sort((a, b) => (b._qualityScore || 0) - (a._qualityScore || 0));
  return filtered;
}

const r = $input.first().json;
const items = r.results || [];
const filtered = applyQualityFilter(items);
const out = filtered.slice(0, 10).map(i => ({
  json: { title: i.title || '', description: (i.description || i.snippet || '').slice(0, 1500), url: i.url || '', source: 'brave-news', age: i.age || '', qualityScore: i._qualityScore || 0 }
})).filter(o => o.json.title && o.json.url);
console.log('Yielded ' + out.length + ' filtered news (from ' + items.length + ' raw)');
return out;

